import RNA, itertools, random
target = ".(((((........)((((....))))..))))......."
n=len(target)

def pairs_of(ss):
    st=[];ps=[]
    for i,c in enumerate(ss):
        if c=='(':st.append(i)
        elif c==')':ps.append((st.pop(),i))
    return set(ps)
tpairs=pairs_of(target)

best=None;bestd=999
random.seed(1)
# Try many random sequences, score by bp distance
for trial in range(200000):
    s=''.join(random.choice('ACGU') for _ in range(n))
    mf=RNA.fold(s)[0]
    d=RNA.bp_distance(mf,target)
    if d<bestd:
        bestd=d;best=s
        if d==0:
            print("SOLVED",s);break
print("bestd",bestd,"best",best)
EOF
timeout 120 python3 /tmp/search.py

